// Test: Get OpenToken
pm.test('Status 200', () => pm.response.to.have.status(200));
pm.test('Response contains token', function() {
    const body = pm.response.json();
    // Auto-capture token into environment
    var t = postman.getResponseCookie("apptio-opentoken").value;
    pm.environment.set("apptio-opentoken", t);
    pm.environment.set('token_expires_at', String(Date.now() + 55 * 60 * 1000));
    console.log('[Test] apptio-opentoken captured and stored.');
});

